PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password TEXT NOT NULL, email TEXT NOT NULL UNIQUE DEFAULT '', plan TEXT NOT NULL DEFAULT 'free', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, role TEXT NOT NULL DEFAULT 'user');
CREATE TABLE IF NOT EXISTS waitlist_entries (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'waitlist', status TEXT NOT NULL DEFAULT 'Pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'website', status TEXT NOT NULL DEFAULT 'draft', description TEXT NOT NULL DEFAULT '', framework TEXT NOT NULL DEFAULT 'React + TailwindCSS', url TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS runtime_project_links (project_id INTEGER PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE, agent_id TEXT UNIQUE, agent_is_imported INTEGER NOT NULL DEFAULT 0, preview_url TEXT, deployment_url TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, hosting_provider TEXT NOT NULL DEFAULT 'cloudflare', custom_domain TEXT UNIQUE, custom_origin TEXT, subdomain_slug TEXT UNIQUE, deployment_origin_url TEXT, deployment_script_name TEXT, custom_domain_cloudflare_id TEXT UNIQUE, custom_domain_status TEXT, custom_domain_ssl_status TEXT, custom_domain_dns_records TEXT NOT NULL DEFAULT '[]', custom_domain_error TEXT, custom_domain_checked_at TEXT, custom_domain_migration_state TEXT NOT NULL DEFAULT '{}', custom_domain_secondary TEXT UNIQUE, custom_domain_secondary_cloudflare_id TEXT UNIQUE, custom_domain_secondary_status TEXT, custom_domain_secondary_ssl_status TEXT, custom_domain_secondary_dns_records TEXT NOT NULL DEFAULT '[]', custom_domain_secondary_error TEXT, custom_domain_secondary_checked_at TEXT);
CREATE TABLE IF NOT EXISTS runtime_custom_domain_claims (hostname TEXT PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, role TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, source TEXT NOT NULL DEFAULT 'custom', purpose TEXT NOT NULL DEFAULT 'website', hostname_kind TEXT NOT NULL DEFAULT 'subdomain', is_primary INTEGER NOT NULL DEFAULT 0, redirect_to TEXT, cloudflare_id TEXT UNIQUE, status TEXT, ssl_status TEXT, dns_records TEXT NOT NULL DEFAULT '[]', error TEXT, checked_at TEXT, migration_state TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS runtime_releases (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, commit_hash TEXT NOT NULL, deployment_url TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS runtime_builder_turns (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, mode TEXT NOT NULL DEFAULT 'build', prompt TEXT NOT NULL, response TEXT NOT NULL, changed_files TEXT NOT NULL DEFAULT '[]', commit_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, activity TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS blog_posts (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, slug TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft', keyword TEXT NOT NULL DEFAULT '', word_count INTEGER NOT NULL DEFAULT 0, scheduled_at TEXT, published_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS autoblogger_settings (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE, enabled INTEGER NOT NULL DEFAULT 0, posts_per_day INTEGER NOT NULL DEFAULT 3, writing_style TEXT NOT NULL DEFAULT 'neil-patel', min_word_count INTEGER NOT NULL DEFAULT 2000, keywords TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS seo_settings (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE, meta_title TEXT NOT NULL DEFAULT '', meta_description TEXT NOT NULL DEFAULT '', focus_keyword TEXT NOT NULL DEFAULT '', schema_json TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, favicon_data TEXT NOT NULL DEFAULT '', canonical_url TEXT NOT NULL DEFAULT '', og_title TEXT NOT NULL DEFAULT '', og_description TEXT NOT NULL DEFAULT '', og_image_url TEXT NOT NULL DEFAULT '', allow_indexing INTEGER NOT NULL DEFAULT 1, social_image_data TEXT NOT NULL DEFAULT '', seo_keywords TEXT NOT NULL DEFAULT '', long_tail_keywords TEXT NOT NULL DEFAULT '', preview_image_data TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS site_pages (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, slug TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', page_type TEXT NOT NULL DEFAULT 'standard', content TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS templates (id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, category TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', framework TEXT NOT NULL DEFAULT '', project_type TEXT NOT NULL DEFAULT 'website', tags TEXT NOT NULL DEFAULT '[]', color TEXT NOT NULL DEFAULT 'from-cyan-500 to-blue-600', github_url TEXT NOT NULL DEFAULT '', fork_url TEXT NOT NULL DEFAULT '', featured INTEGER NOT NULL DEFAULT 0, stars INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, token_hash TEXT NOT NULL UNIQUE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS operations (id TEXT PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, status TEXT NOT NULL, input_json TEXT NOT NULL DEFAULT '{}', result_json TEXT, error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, started_at TEXT, finished_at TEXT);
CREATE TABLE IF NOT EXISTS audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_user_id TEXT, action TEXT NOT NULL, project_id INTEGER, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE INDEX IF NOT EXISTS operations_project_idx ON operations(project_id,created_at);
CREATE INDEX IF NOT EXISTS audit_project_idx ON audit_events(project_id,created_at);